#!/usr/bin/env bash
# build_mcuboot.sh [cpu_hz] - MCUboot for the AXC3000 Nios V/g, into
# niosv_zephyr/zephyr/build_mcuboot. cpu_hz must match the hardware's
# CPU_CLOCK_MHZ (default 120 MHz).
set -euo pipefail
HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
NZ="$HERE/.."
CPU_HZ="${1:-120000000}"
mkdir -p "$NZ/zephyr/build_mcuboot" "$NZ/zephyr/build_mcuboot_small"
# the CPU overlay apps/niosv_cpu_clock.cmake generates for the apps
cat > "$NZ/zephyr/build_mcuboot.cpu.overlay" <<OVL
/* generated by mcuboot/build_mcuboot.sh */
&cpu0 {
	clock-frequency = <$CPU_HZ>;
};
OVL
# our MCUboot patches (mcuboot/patches/*.patch), applied once to the
# workspace's MCUboot (zephyr/bootloader/mcuboot)
MCUBOOT_SRC="$NZ/zephyr/bootloader/mcuboot"
for p in "$HERE"/patches/*.patch; do
    if git -C "$MCUBOOT_SRC" apply --reverse --check "$p" 2>/dev/null; then
        continue                                    # already applied
    fi
    git -C "$MCUBOOT_SRC" apply "$p"
    echo "applied $(basename "$p")"
done

source "$NZ/.venv/bin/activate"
cd "$NZ/zephyr"
OVERLAYS="$NZ/zephyr/build_mcuboot.cpu.overlay"
# not niosv_g_hyperram_xip: MCUboot runs from on-chip RAM; the HyperRAM
# address it copies to is CONFIG_BOOT_IMAGE_EXECUTABLE_RAM_* (mcuboot.conf)
# SMALL_OCRAM=1: the small on-chip RAM hardware variant (68 KB ram0, an 8 KB
# data cache, MCUboot's RAM in the HyperRAM) - into build_mcuboot_small
BOOTINFO=niosv_g_bootinfo
MCUBOOT_OVERLAY="$HERE/mcuboot.overlay"
CONFS="$HERE/mcuboot.conf"
BUILD=build_mcuboot
if [ "${SMALL_OCRAM:-0}" = 1 ]; then
    BOOTINFO=niosv_g_bootinfo_small
    MCUBOOT_OVERLAY="$HERE/mcuboot_small.overlay"
    CONFS="$CONFS;$NZ/zephyr_overlays/niosv_g_small_ocram.conf"
    BUILD=build_mcuboot_small
fi
for o in niosv_g_axc3000 niosv_g_uart_fifo niosv_g_sdm_qspi niosv_g_flash_layout $BOOTINFO; do
    OVERLAYS="$OVERLAYS;$NZ/zephyr_overlays/$o.overlay"
done
west build -p always -b niosv_g -d $BUILD bootloader/mcuboot/boot/zephyr -- \
    -DEXTRA_DTC_OVERLAY_FILE="$OVERLAYS;$MCUBOOT_OVERLAY" \
    -DEXTRA_CONF_FILE="$CONFS" \
    -DEXTRA_ZEPHYR_MODULES="$NZ/zephyr_module"
